CREATE TABLE IF NOT EXISTS salary_structures(
salary_structure_id BIGSERIAL PRIMARY KEY,role_id BIGINT,role_name VARCHAR(100) NOT NULL,basic_salary NUMERIC(14,2) NOT NULL,hra NUMERIC(14,2) NOT NULL,allowances NUMERIC(14,2) NOT NULL,deductions NUMERIC(14,2) NOT NULL,monthly_gross_salary NUMERIC(14,2) NOT NULL,monthly_net_salary NUMERIC(14,2) NOT NULL,currency VARCHAR(10) NOT NULL,effective_from DATE NOT NULL,status VARCHAR(20) NOT NULL,created_by BIGINT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS staff_bank_accounts(bank_account_id BIGSERIAL PRIMARY KEY,staff_id BIGINT NOT NULL UNIQUE,account_holder_name VARCHAR(150) NOT NULL,bank_name VARCHAR(150) NOT NULL,account_number VARCHAR(80) NOT NULL,ifsc_code VARCHAR(30) NOT NULL,branch_name VARCHAR(150),account_type VARCHAR(50),status VARCHAR(20) NOT NULL,created_by BIGINT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS payroll(payroll_id BIGSERIAL PRIMARY KEY,branch_id BIGINT NOT NULL,staff_id BIGINT NOT NULL,role_id BIGINT,department VARCHAR(100),month INTEGER NOT NULL,year INTEGER NOT NULL,total_working_days INTEGER NOT NULL,present_days INTEGER NOT NULL,absent_days INTEGER NOT NULL,half_days INTEGER NOT NULL,leave_days INTEGER NOT NULL,basic_salary NUMERIC(14,2) NOT NULL,hra NUMERIC(14,2) NOT NULL,allowances NUMERIC(14,2) NOT NULL,bonus NUMERIC(14,2) NOT NULL,gross_salary NUMERIC(14,2) NOT NULL,attendance_deduction NUMERIC(14,2) NOT NULL,other_deductions NUMERIC(14,2) NOT NULL,net_salary NUMERIC(14,2) NOT NULL,payment_status VARCHAR(30) NOT NULL,payment_mode VARCHAR(30) NOT NULL,transaction_id VARCHAR(120),paid_at TIMESTAMPTZ,remarks VARCHAR(500),generated_by BIGINT,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT uk_payroll_staff_period UNIQUE(staff_id,month,year));
CREATE TABLE IF NOT EXISTS payroll_payment_batches(payment_batch_id BIGSERIAL PRIMARY KEY,branch_id BIGINT,month INTEGER NOT NULL,year INTEGER NOT NULL,total_staff INTEGER NOT NULL,total_amount NUMERIC(16,2) NOT NULL,payment_mode VARCHAR(30) NOT NULL,status VARCHAR(30) NOT NULL,created_by BIGINT,created_at TIMESTAMPTZ,completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS salary_slips(salary_slip_id BIGSERIAL PRIMARY KEY,payroll_id BIGINT NOT NULL UNIQUE REFERENCES payroll(payroll_id) ON DELETE CASCADE,staff_id BIGINT NOT NULL,month INTEGER NOT NULL,year INTEGER NOT NULL,salary_slip_url VARCHAR(500) NOT NULL,generated_at TIMESTAMPTZ NOT NULL,sent_email_status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
